-- ============================================================
-- ElectriSys — Ampliación del dataset del asistente NLP en Oracle 23ai
-- Agrega 2177 frases de entrenamiento nuevas (las filas de
-- nlp-service/data/intents_dataset.csv posteriores a las 374 originales)
-- a la tabla NLP_FRASES creada por 12_nlp_dataset.sql.
--
-- Ejecutar conectado como ELECTRISYS, después de 12_nlp_dataset.sql.
-- El archivo está en UTF-8: usar NLS_LANG=.AL32UTF8 al correr sqlplus.
--
-- Es idempotente: cada INSERT lleva NOT EXISTS por (texto, intención), así que
-- puede ejecutarse varias veces sin duplicar frases ni tocar las que ya existen.
-- No borra ni modifica nada. Cada frase queda con conjunto = 'entrenamiento'.
--
-- Frases nuevas por intención:
--   buscar_repuesto: 275
--   recomendar_sustituto: 263
--   consultar_stock: 311
--   consultar_precio: 291
--   consultar_compatibilidad: 297
--   saludo_despedida: 340
--   fuera_de_dominio: 400
-- ============================================================
SET DEFINE OFF;
SET SQLBLANKLINES ON;

-- buscar_repuesto (275 frases)

-- recomendar_sustituto (263 frases)

-- consultar_stock (311 frases)

-- consultar_precio (291 frases)

-- consultar_compatibilidad (297 frases)

-- saludo_despedida (340 frases)

-- fuera_de_dominio (400 frases)

COMMIT;

-- Verificación (solo lectura): frases de entrenamiento por intención.
SELECT i.nombre, COUNT(*) AS frases
  FROM nlp_frases f JOIN nlp_intenciones i ON i.id = f.intencion_id
 WHERE f.conjunto = 'entrenamiento'
 GROUP BY i.nombre ORDER BY i.nombre;
